// Men's Social — Step 75: the Studio makes big videos smaller (720p) before uploading, so they fit under 50 MB.
// ONE file: it writes the changed code into your project, nothing else.
//
// Put this file in your project folder (next to package.json), then:
//   node apply-step-75.mjs          -> writes the changes (a few seconds)
//   npm run dev                     -> test at http://localhost:3000
//   node apply-step-75.mjs commit   -> build check, then commit and push to GitHub
// A file that's replaced is backed up as <name>.bak first.

import { spawnSync } from "node:child_process";
import { existsSync, readFileSync, writeFileSync, copyFileSync, mkdirSync } from "node:fs";
import { dirname } from "node:path";

const TEXT = {"src/components/studio/Editor.tsx": "\"use client\";\n\nimport { useEffect, useMemo, useRef, useState } from \"react\";\nimport Link from \"next/link\";\nimport { useRouter } from \"next/navigation\";\nimport {\n  AlertTriangle,\n  ArrowLeft,\n  Archive,\n  CheckCircle2,\n  Clock,\n  Copy,\n  Film,\n  History,\n  Mic,\n  ImagePlus,\n  MapPin,\n  Loader2,\n  OctagonX,\n  Plus,\n  Trash2,\n  X,\n} from \"lucide-react\";\nimport Preview from \"./Preview\";\nimport { YouTubeFrame } from \"@/components/media/YouTubeFrame\";\nimport { cleanYouTubeUrl, isYouTubeShort, youtubeId } from \"@/lib/content/youtube\";\nimport { MAX_VIDEO_BYTES } from \"@/lib/content/repo\";\nimport { canShrink, shrinkVideo } from \"@/lib/studio/shrinkVideo\";\nimport { useStudio } from \"@/components/admin/AdminShell\";\nimport type { Version } from \"@/lib/content/repo\";\nimport { Notice } from \"./StudioGate\";\nimport {\n  displayStatus,\n  STATUS_LABEL,\n  STATUS_STYLE,\n} from \"@/lib/admin/contentStatus\";\nimport { Confirm, Drawer, btn } from \"@/components/admin/ui\";\nimport { useToast } from \"@/components/motion/Toast\";\nimport { LIBRARY, TOPICS } from \"@/lib/content/library\";\nimport { getContentRepo } from \"@/lib/content/repo\";\nimport { KIND_LABEL } from \"@/lib/content/select\";\nimport type {\n  ContentItem,\n  ContentKind,\n  ContentStatus,\n  QuizQuestion,\n  ToolId,\n} from \"@/lib/content/types\";\nimport { checkClaims } from \"@/lib/studio/claims\";\nimport { placesOf, presetFor, type PlaceId } from \"@/lib/studio/places\";\nimport type { TopicId } from \"@/lib/content/types\";\nimport {\n  blankItem,\n  fromLines,\n  fromParagraphs,\n  ID_RULE,\n  publishProblems,\n  slugify,\n  toLines,\n  toParagraphs,\n} from \"@/lib/studio/validate\";\n\nconst KINDS: ContentKind[] = [\n  \"reel\",\n  \"article\",\n  \"guide\",\n  \"expert\",\n  \"video\",\n  \"quiz\",\n  \"tool\",\n  \"audio\",\n  \"infographic\",\n];\nconst TONES: ContentItem[\"cover\"][\"tone\"][] = [\n  \"forest\",\n  \"night\",\n  \"mint\",\n  \"sand\",\n  \"clay\",\n];\nconst MOTIFS: ContentItem[\"cover\"][\"motif\"][] = [\n  \"rings\",\n  \"waves\",\n  \"arc\",\n  \"grid\",\n  \"dots\",\n];\nconst TONE_SWATCH: Record<string, string> = {\n  forest: \"#0f5c46\",\n  night: \"#06261d\",\n  mint: \"#dff3ea\",\n  sand: \"#f1e8d8\",\n  clay: \"#efdcd0\",\n};\nconst TOOLS: { id: ToolId; label: string }[] = [\n  { id: \"pelvic-floor\", label: \"Pelvic floor trainer\" },\n  { id: \"doctor-check\", label: \"Should I see a doctor? check\" },\n];\n\ntype Texts = { body: string; bodySw: string; keyPoints: string; tags: string };\nconst textsOf = (c: ContentItem): Texts => ({\n  body: fromParagraphs(c.body),\n  bodySw: fromParagraphs(c.bodySw),\n  keyPoints: fromLines(c.keyPoints),\n  tags: c.tags.join(\", \"),\n});\n\nconst compose = (draft: ContentItem, texts: Texts): ContentItem => ({\n  ...draft,\n  body: toParagraphs(texts.body),\n  bodySw: toParagraphs(texts.bodySw),\n  keyPoints: toLines(texts.keyPoints),\n  tags: texts.tags\n    .split(\",\")\n    .map((t) => t.trim().toLowerCase())\n    .filter(Boolean),\n});\n\ntype Loaded =\n  | { base: ContentItem; status: ContentStatus | null; copyOfBuiltIn: boolean }\n  | \"missing\";\n\nexport default function Editor({\n  id,\n  preset,\n  copyOf,\n}: {\n  id: string | null;\n  preset?: { place: PlaceId | null; topic: TopicId | null };\n  /** Duplicate: start a new item from this one */\n  copyOf?: string | null;\n}) {\n  const studio = useStudio();\n  const canPublish = studio.can(\"content.publish\");\n  const fresh = () =>\n    presetFor(blankItem(), preset?.place ?? null, preset?.topic ?? null);\n  const router = useRouter();\n  const showToast = useToast();\n  const repo = getContentRepo();\n\n  const [loaded, setLoaded] = useState<Loaded | null>(\n    id || copyOf ? null : { base: fresh(), status: null, copyOfBuiltIn: false },\n  );\n  const [takenIds, setTakenIds] = useState<Set<string>>(\n    new Set(LIBRARY.map((c) => c.id)),\n  );\n  const [loadError, setLoadError] = useState<string | null>(null);\n\n  const [draft, setDraft] = useState<ContentItem>(blankItem());\n  const [texts, setTexts] = useState<Texts>(textsOf(blankItem()));\n  const [savedJson, setSavedJson] = useState(\"\");\n  const [idTouched, setIdTouched] = useState(false);\n  const [busy, setBusy] = useState<string | null>(null);\n  const [error, setError] = useState<string | null>(null);\n  const fileInput = useRef<HTMLInputElement>(null);\n  const videoInput = useRef<HTMLInputElement>(null);\n  const quickVideo = useRef<HTMLInputElement>(null);\n  // Reels get a short form (video, caption, topic). \"More options\" opens the full editor.\n  const [fullForm, setFullForm] = useState(false);\n  const [ytBlocked, setYtBlocked] = useState<string | null>(null);\n  // Big videos are made smaller in the browser before upload (Step 75)\n  const [shrink, setShrink] = useState<{ pct: number; pass: number; mb: number } | null>(null);\n  const shrinkAbort = useRef<AbortController | null>(null);\n  const audioInput = useRef<HTMLInputElement>(null);\n  const [versions, setVersions] = useState<Version[] | null>(null);\n  const [showHistory, setShowHistory] = useState(false);\n  const [confirmDelete, setConfirmDelete] = useState(false);\n\n  // Load: from the database first, otherwise a built-in item to copy\n  useEffect(() => {\n    repo\n      .listAll()\n      .then((all) => {\n        setTakenIds(\n          new Set([...LIBRARY.map((c) => c.id), ...all.map((c) => c.id)]),\n        );\n        const taken = new Set([\n          ...LIBRARY.map((c) => c.id),\n          ...all.map((c) => c.id),\n        ]);\n        if (!id && copyOf) {\n          // Duplicate: same content, new address, saved as a new draft\n          const src =\n            all.find((c) => c.id === copyOf) ??\n            LIBRARY.find((c) => c.id === copyOf);\n          if (!src) return setLoaded(\"missing\");\n          let newId = slugify(src.title + \" copy\");\n          for (let n = 2; taken.has(newId); n++)\n            newId = slugify(src.title + \" copy \" + n);\n          setLoaded({\n            base: {\n              ...src,\n              id: newId,\n              title: src.title + \" (copy)\",\n              status: \"draft\",\n              featured: undefined,\n              publishAt: undefined,\n              reviewNote: undefined,\n              fixture: false,\n              builtIn: false,\n              updatedAt: undefined,\n            },\n            status: null,\n            copyOfBuiltIn: false,\n          });\n          return;\n        }\n        if (!id) return;\n        const mine = all.find((c) => c.id === id);\n        const builtIn = LIBRARY.find((c) => c.id === id);\n        if (mine)\n          setLoaded({\n            base: mine,\n            status: mine.status ?? \"draft\",\n            copyOfBuiltIn: Boolean(builtIn),\n          });\n        else if (builtIn)\n          setLoaded({\n            base: {\n              ...builtIn,\n              fixture: false,\n              builtIn: false,\n              status: \"draft\",\n            },\n            status: null,\n            copyOfBuiltIn: true,\n          });\n        else setLoaded(\"missing\");\n      })\n      .catch((e: Error) => setLoadError(e.message));\n  }, [id, repo, copyOf]);\n\n  useEffect(() => {\n    if (!loaded || loaded === \"missing\") return;\n    setDraft(loaded.base);\n    setTexts(textsOf(loaded.base));\n    // A Kiswahili translation handed over from Admin → AI: filled in, not saved, marked AI-assisted\n    try {\n      const key = `ms_ai_sw:${loaded.base.id}`;\n      const raw = sessionStorage.getItem(key);\n      if (raw) {\n        sessionStorage.removeItem(key);\n        const sw = JSON.parse(raw) as {\n          titleSw?: string;\n          summarySw?: string;\n          bodySw?: string[];\n        };\n        setDraft((d) => ({\n          ...d,\n          titleSw: sw.titleSw || d.titleSw,\n          summarySw: sw.summarySw || d.summarySw,\n          aiGenerated: true,\n        }));\n        if (Array.isArray(sw.bodySw))\n          setTexts((t) => ({ ...t, bodySw: fromParagraphs(sw.bodySw) }));\n        showToast(\"Kiswahili from AI filled in · check it, then save\");\n      }\n    } catch {}\n    setSavedJson(\n      loaded.status\n        ? JSON.stringify(compose(loaded.base, textsOf(loaded.base)))\n        : \"\",\n    );\n  }, [loaded, showToast]);\n\n  // The item as it will be saved\n  const item: ContentItem = useMemo(\n    () => compose(draft, texts),\n    [draft, texts],\n  );\n\n  const status = loaded && loaded !== \"missing\" ? loaded.status : null; // null = not in the database yet\n  const isNew = status === null;\n  const claims = useMemo(() => checkClaims(item), [item]);\n  const problems = useMemo(() => publishProblems(item), [item]);\n  const idTaken =\n    isNew &&\n    !(loaded !== \"missing\" && loaded?.copyOfBuiltIn) &&\n    takenIds.has(item.id);\n  const dirty = JSON.stringify(item) !== savedJson;\n\n  // Warn before leaving with unsaved changes\n  useEffect(() => {\n    if (!dirty) return;\n    const warn = (e: BeforeUnloadEvent) => e.preventDefault();\n    window.addEventListener(\"beforeunload\", warn);\n    return () => window.removeEventListener(\"beforeunload\", warn);\n  }, [dirty]);\n\n  const set = <K extends keyof ContentItem>(key: K, value: ContentItem[K]) =>\n    setDraft((d) => ({ ...d, [key]: value }));\n  const setText = (key: keyof Texts, value: string) =>\n    setTexts((t) => ({ ...t, [key]: value }));\n\n  function setTitle(title: string) {\n    setDraft((d) => ({\n      ...d,\n      title,\n      id: isNew && !idTouched && !loadedCopy() ? slugify(title) : d.id,\n    }));\n  }\n  const loadedCopy = () =>\n    loaded !== null && loaded !== \"missing\" && loaded.copyOfBuiltIn;\n\n  async function save(next: ContentStatus) {\n    setError(null);\n    if (!ID_RULE.test(item.id))\n      return setError(\"Add a title first (it makes the web address).\");\n    if (idTaken)\n      return setError(\n        `The web address \"${item.id}\" is already used. Change it below the title.`,\n      );\n    if ((next === \"published\" || next === \"review\") && problems.length)\n      return setError(\n        next === \"review\"\n          ? \"Not ready for review yet. See the checklist.\"\n          : \"Not ready to publish yet. See the checklist.\",\n      );\n    const scheduled =\n      next === \"published\" &&\n      item.publishAt &&\n      new Date(item.publishAt) > new Date();\n    setBusy(next);\n    try {\n      const saved = await repo.save(item, next);\n      const merged = {\n        ...item,\n        status: saved.status,\n        updatedAt: saved.updatedAt,\n      };\n      setSavedJson(JSON.stringify(merged));\n      setDraft(merged);\n      setLoaded({ base: merged, status: next, copyOfBuiltIn: loadedCopy() });\n      showToast(\n        scheduled\n          ? `Scheduled for ${new Date(item.publishAt!).toLocaleString(\"en-GB\", { day: \"numeric\", month: \"short\", hour: \"2-digit\", minute: \"2-digit\" })}`\n          : next === \"published\"\n            ? status === \"published\"\n              ? \"Live version updated\"\n              : \"Published\"\n            : next === \"review\"\n              ? \"Sent for review\"\n              : next === \"archived\"\n                ? \"Archived\"\n                : \"Draft saved\",\n      );\n      if (isNew)\n        router.replace(`/studio/edit?id=${encodeURIComponent(item.id)}`);\n    } catch (e) {\n      setError((e as Error).message);\n    } finally {\n      setBusy(null);\n    }\n  }\n\n  async function openHistory() {\n    setShowHistory(true);\n    setVersions(null);\n    try {\n      setVersions(await repo.listVersions(item.id));\n    } catch (e) {\n      setShowHistory(false);\n      setError((e as Error).message);\n    }\n  }\n\n  function loadVersion(v: Version) {\n    // Keeps this item's address; you review the old text, then save or publish it again\n    const restored = {\n      ...v.item,\n      id: item.id,\n      status: item.status,\n      updatedAt: item.updatedAt,\n    };\n    setDraft(restored);\n    setTexts(textsOf(restored));\n    setShowHistory(false);\n    showToast(\"Older version loaded · save to keep it\");\n  }\n\n  async function uploadAudio(file: File | undefined) {\n    if (!file) return;\n    if (!ID_RULE.test(item.id))\n      return setError(\"Add a title first, then the audio.\");\n    setError(null);\n    setBusy(\"audio\");\n    try {\n      set(\"audioUrl\", await repo.uploadAudio(file, item.id));\n      showToast(\"Audio added · save to keep it\");\n    } catch (e) {\n      setError((e as Error).message);\n    } finally {\n      setBusy(null);\n      if (audioInput.current) audioInput.current.value = \"\";\n    }\n  }\n\n  async function remove() {\n    setConfirmDelete(false);\n    setBusy(\"delete\");\n    try {\n      await repo.remove(item.id);\n      setSavedJson(JSON.stringify(item));\n      showToast(\"Deleted\");\n      router.push(\"/studio/content\");\n    } catch (e) {\n      setError((e as Error).message);\n      setBusy(null);\n    }\n  }\n\n  async function upload(file: File | undefined) {\n    if (!file) return;\n    if (!ID_RULE.test(item.id))\n      return setError(\"Add a title first, then the photo.\");\n    setError(null);\n    setBusy(\"image\");\n    try {\n      set(\"coverImageUrl\", await repo.uploadImage(file, item.id));\n      showToast(\"Photo added · save to keep it\");\n    } catch (e) {\n      setError((e as Error).message);\n    } finally {\n      setBusy(null);\n      if (fileInput.current) fileInput.current.value = \"\";\n    }\n  }\n\n  async function uploadVideo(file: File | undefined) {\n    if (!file) return;\n    let vid = item.id;\n    if (!ID_RULE.test(vid)) {\n      if (item.kind !== \"reel\")\n        return setError(\"Add a title first, then the video.\");\n      // A reel can start with the video: it gets its own web address\n      vid = `reel-${Date.now().toString(36)}`;\n      setIdTouched(true);\n      set(\"id\", vid);\n    }\n    setError(null);\n    setBusy(\"video\");\n    try {\n      let toSend = file;\n      if (file.size > MAX_VIDEO_BYTES) {\n        const mb = Math.round(file.size / 1048576);\n        if (!canShrink())\n          throw new Error(`This video is ${mb} MB (the limit is 50 MB). Open the Studio in Chrome to make it smaller here, or shrink it in CapCut (Export → 720p).`);\n        const ac = new AbortController();\n        shrinkAbort.current = ac;\n        setShrink({ pct: 0, pass: 1, mb });\n        let last = -1;\n        toSend = await shrinkVideo(file, {\n          signal: ac.signal,\n          onProgress: (f, pass) => {\n            const pct = Math.floor(f * 100) + pass * 1000;\n            if (pct === last) return;\n            last = pct;\n            setShrink({ pct: f, pass, mb });\n          },\n        });\n        setShrink(null);\n        showToast(`Made smaller: ${mb} MB → ${Math.max(1, Math.round(toSend.size / 1048576))} MB · uploading`);\n      }\n      set(\"videoUrl\", await repo.uploadVideo(toSend, vid));\n      showToast(\"Video added · save to keep it\");\n    } catch (e) {\n      setError((e as Error).message);\n    } finally {\n      setShrink(null);\n      shrinkAbort.current = null;\n      setBusy(null);\n      if (videoInput.current) videoInput.current.value = \"\";\n      if (quickVideo.current) quickVideo.current.value = \"\";\n    }\n  }\n\n  if (loadError) return <Notice title=\"Couldn't load\">{loadError}</Notice>;\n  if (loaded === \"missing\")\n    return (\n      <Notice title=\"Not found\">\n        Nothing with the address &ldquo;{id}&rdquo;.{\" \"}\n        <Link href=\"/studio\" className=\"font-semibold text-forest\">\n          Back to content\n        </Link>\n      </Notice>\n    );\n  if (!loaded)\n    return (\n      <div className=\"flex justify-center py-20 text-ink-soft\">\n        <Loader2 className=\"animate-spin\" />\n      </div>\n    );\n\n  const quick = item.kind === \"reel\" && !fullForm;\n  const yt = youtubeId(item.videoUrl);\n  /** A pasted video link: YouTube links are tidied; a reel gets a web address so the caption can come later. */\n  function pasteVideo(raw: string) {\n    const v = raw.trim();\n    const link = youtubeId(v) ? cleanYouTubeUrl(v)! : v;\n    setYtBlocked(null);\n    setDraft((d) => ({\n      ...d,\n      videoUrl: link || undefined,\n      ...(d.kind === \"reel\" && link && !ID_RULE.test(d.id) ? { id: `reel-${Date.now().toString(36)}` } : {}),\n    }));\n    if (item.kind === \"reel\" && link && !ID_RULE.test(item.id)) setIdTouched(true);\n  }\n  const shrinkNote = shrink ? (\n    <div className=\"space-y-2 rounded-2xl bg-mint/30 p-3 text-sm ring-1 ring-forest/20\" role=\"status\">\n      <p className=\"font-semibold\">\n        Making the video smaller… {Math.round(shrink.pct * 100)}%{shrink.pass > 1 ? \" (second try, a bit smaller)\" : \"\"}\n      </p>\n      <div className=\"h-2 overflow-hidden rounded-full bg-line\">\n        <div className=\"h-full bg-forest transition-[width]\" style={{ width: `${shrink.pct * 100}%` }} />\n      </div>\n      <p className=\"text-xs text-ink-soft\">\n        It&apos;s {shrink.mb} MB, over the 50 MB limit, so it&apos;s being made 720p. This takes about as long as the video itself. Keep this page open and on screen.\n      </p>\n      <button type=\"button\" className={btn.small} onClick={() => shrinkAbort.current?.abort()}>\n        <X size={13} /> Stop\n      </button>\n    </div>\n  ) : null;\n  const ytNote = yt ? (\n    ytBlocked === item.videoUrl ? (\n      <p className=\"text-xs font-semibold text-red-700\">\n        YouTube says this video&apos;s owner doesn&apos;t allow it to play in other apps (or it&apos;s private or removed). Men will see &ldquo;This video can&apos;t play here&rdquo;. Use another video.\n      </p>\n    ) : (\n      <p className=\"text-xs text-ink-soft\">\n        YouTube video · plays inside the app{isYouTubeShort(item.videoUrl) ? \" (Short, upright)\" : \"\"}. YouTube may show its logo, and ads if the channel has them.\n      </p>\n    )\n  ) : null;\n  const caption = item.summary || item.title;\n  /** One caption, written once: the first line is the title, the whole thing the caption, same in both languages. */\n  function setCaption(text: string) {\n    const first = text.split(\"\\n\")[0].trim();\n    const title =\n      first.length > 100 ? first.slice(0, 100).replace(/\\s+\\S*$/, \"\") : first;\n    setDraft((d) => ({\n      ...d,\n      title,\n      titleSw: title || undefined,\n      summary: text,\n      summarySw: text || undefined,\n      inManFeed: false,\n      id: isNew && !idTouched && !loadedCopy() ? slugify(title) : d.id,\n    }));\n  }\n\n  const blocks = claims.filter((c) => c.level === \"block\");\n  const warns = claims.filter((c) => c.level === \"warn\");\n\n  return (\n    <div className=\"space-y-5\">\n      <div className=\"flex flex-wrap items-center justify-between gap-3\">\n        <Link\n          href=\"/studio/content\"\n          className=\"flex items-center gap-1 text-sm text-ink-soft\"\n        >\n          <ArrowLeft size={16} /> All content\n        </Link>\n        <div className=\"flex flex-wrap items-center gap-2\">\n          {status && (\n            <>\n              <button type=\"button\" onClick={openHistory} className={btn.small}>\n                <History size={13} /> History\n              </button>\n              <Link\n                href={`/studio/edit?copy=${encodeURIComponent(item.id)}`}\n                className={btn.small}\n              >\n                <Copy size={13} /> Duplicate\n              </Link>\n            </>\n          )}\n          <span\n            className={`rounded-full px-3 py-1 text-xs font-semibold ring-1 ${status ? STATUS_STYLE[displayStatus({ status, publishAt: loaded.base.publishAt })] : \"bg-bg text-ink-soft ring-line\"}`}\n          >\n            {status\n              ? STATUS_LABEL[\n                  displayStatus({ status, publishAt: loaded.base.publishAt })\n                ]\n              : \"Not saved yet\"}\n            {dirty && status ? \" · unsaved changes\" : \"\"}\n          </span>\n        </div>\n      </div>\n      {status === \"review\" && loaded.base.reviewNote && (\n        <p className=\"rounded-2xl bg-amber-50 px-4 py-3 text-sm text-amber-900\">\n          <b>Review note:</b> {loaded.base.reviewNote}\n        </p>\n      )}\n\n      {loaded.copyOfBuiltIn && (\n        <p className=\"rounded-2xl bg-mint/60 px-4 py-3 text-sm text-forest-deep\">\n          {isNew\n            ? \"You're editing a copy of a built-in item. When you publish it, your version replaces the built-in one in the app.\"\n            : \"This is your edited copy of a built-in item. Published = your version shows in the app.\"}\n        </p>\n      )}\n\n      <div className=\"grid gap-6 lg:grid-cols-[minmax(0,1fr)_360px]\">\n        <div className=\"space-y-5\">\n          {quick ? (\n            <Section title=\"New reel\">\n              <div className=\"flex flex-wrap items-center gap-2 text-xs text-ink-soft\">\n                Making something else?\n                {KINDS.filter((k) => k !== \"reel\")\n                  .slice(0, 3)\n                  .map((k) => (\n                    <button\n                      key={k}\n                      type=\"button\"\n                      onClick={() => set(\"kind\", k)}\n                      className=\"font-semibold text-forest underline\"\n                    >\n                      {KIND_LABEL[k]}\n                    </button>\n                  ))}\n                <button\n                  type=\"button\"\n                  onClick={() => setFullForm(true)}\n                  className=\"font-semibold text-forest underline\"\n                >\n                  More…\n                </button>\n              </div>\n\n              {/* 1. The video */}\n              {item.videoUrl ? (\n                <div className=\"flex items-end gap-3\">\n                  {yt ? (\n                    <YouTubeFrame\n                      id={yt}\n                      controls\n                      title={item.title || \"Reel\"}\n                      onBlocked={() => setYtBlocked(item.videoUrl ?? null)}\n                      className=\"aspect-[9/16] w-36 shrink-0 rounded-2xl\"\n                    />\n                  ) : (\n                    <video\n                      src={item.videoUrl}\n                      controls\n                      playsInline\n                      preload=\"metadata\"\n                      className=\"aspect-[9/16] w-36 shrink-0 rounded-2xl bg-black\"\n                    />\n                  )}\n                  <div className=\"space-y-2\">\n                    <button\n                      type=\"button\"\n                      onClick={() => quickVideo.current?.click()}\n                      disabled={busy === \"video\"}\n                      className={btn.small}\n                    >\n                      {busy === \"video\" ? (\n                        <Loader2 size={13} className=\"animate-spin\" />\n                      ) : (\n                        <Film size={13} />\n                      )}{\" \"}\n                      Change video\n                    </button>\n                  </div>\n                </div>\n              ) : (\n                <button\n                  type=\"button\"\n                  onClick={() => quickVideo.current?.click()}\n                  disabled={busy === \"video\"}\n                  className=\"flex w-full flex-col items-center justify-center gap-2 rounded-3xl border-2 border-dashed border-forest/40 bg-mint/20 py-10 text-forest disabled:opacity-60\"\n                >\n                  {busy === \"video\" ? (\n                    <Loader2 size={28} className=\"animate-spin\" />\n                  ) : (\n                    <Film size={28} />\n                  )}\n                  <span className=\"font-bold\">\n                    {busy === \"video\" ? (shrink ? \"Making it smaller…\" : \"Uploading…\") : \"Choose the video\"}\n                  </span>\n                  <span className=\"text-xs text-ink-soft\">\n                    Upright. Big videos are made smaller for you.\n                  </span>\n                </button>\n              )}\n              <input\n                ref={quickVideo}\n                type=\"file\"\n                accept=\"video/mp4,video/webm,video/quicktime\"\n                className=\"hidden\"\n                onChange={(e) => uploadVideo(e.target.files?.[0])}\n              />\n              <Field label=\"Or paste a YouTube link\" hint=\"A Short or any YouTube video. It plays inside the app, no upload needed.\">\n                <input\n                  className={input}\n                  type=\"url\"\n                  inputMode=\"url\"\n                  placeholder=\"https://youtube.com/shorts/…\"\n                  value={item.videoUrl && !item.videoUrl.includes(\"supabase.co\") ? item.videoUrl : \"\"}\n                  onChange={(e) => pasteVideo(e.target.value)}\n                />\n              </Field>\n              {shrinkNote}\n              {ytNote}\n\n              {/* 2. The caption */}\n              <Field\n                label=\"Caption\"\n                hint=\"Write it once, in Kiswahili or English. The first line is the title.\"\n              >\n                <textarea\n                  className={`${input} min-h-24`}\n                  value={caption}\n                  onChange={(e) => setCaption(e.target.value)}\n                  placeholder=\"e.g. Mchanganyiko wa vitunguu saumu, tangawizi na manjano\"\n                  maxLength={600}\n                />\n              </Field>\n\n              {/* 3. The topic */}\n              <Field group label=\"Topic\">\n                <div className=\"flex flex-wrap gap-1.5\">\n                  {TOPICS.map((t) => (\n                    <button\n                      key={t.id}\n                      type=\"button\"\n                      onClick={() => set(\"topic\", t.id)}\n                      className={`rounded-full px-3 py-1.5 text-xs font-semibold ring-1 ${item.topic === t.id ? \"bg-forest text-white ring-forest\" : \"ring-line\"}`}\n                    >\n                      {t.short}\n                    </button>\n                  ))}\n                </div>\n              </Field>\n\n              {(problems.length > 0 || blocks.length > 0) &&\n                (item.videoUrl || caption) && (\n                  <ul className=\"space-y-1 rounded-2xl bg-amber-50 px-4 py-3 text-xs text-amber-900\">\n                    {problems.map((p) => (\n                      <li key={p}>• {p}</li>\n                    ))}\n                  </ul>\n                )}\n              <button\n                type=\"button\"\n                onClick={() => setFullForm(true)}\n                className=\"text-xs font-semibold text-ink-soft underline\"\n              >\n                More options (cover photo, schedule, separate Kiswahili text…)\n              </button>\n            </Section>\n          ) : (\n            <>\n              {/* Basics */}\n              <Section title=\"What is it?\">\n                <div className=\"flex flex-wrap gap-2\">\n                  {KINDS.map((k) => (\n                    <Chip\n                      key={k}\n                      on={item.kind === k}\n                      onClick={() => set(\"kind\", k)}\n                    >\n                      {KIND_LABEL[k]}\n                    </Chip>\n                  ))}\n                </div>\n                <Field group label=\"Topic\">\n                  <div className=\"flex flex-wrap gap-2\">\n                    {TOPICS.map((t) => (\n                      <Chip\n                        key={t.id}\n                        on={item.topic === t.id}\n                        onClick={() => set(\"topic\", t.id)}\n                      >\n                        {t.title}\n                      </Chip>\n                    ))}\n                  </div>\n                </Field>\n              </Section>\n\n              <Section title=\"Title and summary\">\n                <Field label=\"Title (English)\">\n                  <input\n                    className={input}\n                    value={item.title}\n                    onChange={(e) => setTitle(e.target.value)}\n                    placeholder=\"e.g. Why sleep matters for erections\"\n                    maxLength={160}\n                  />\n                </Field>\n                <Field\n                  label=\"Web address\"\n                  hint={\n                    isNew && !loaded.copyOfBuiltIn\n                      ? \"Made from the title. Can't change after the first save.\"\n                      : \"Fixed after the first save.\"\n                  }\n                >\n                  <input\n                    className={`${input} font-mono text-xs`}\n                    value={item.id}\n                    disabled={!isNew || loaded.copyOfBuiltIn}\n                    onChange={(e) => {\n                      setIdTouched(true);\n                      set(\n                        \"id\",\n                        e.target.value\n                          .toLowerCase()\n                          .replace(/[^a-z0-9-]/g, \"-\"),\n                      );\n                    }}\n                  />\n                  {idTaken && (\n                    <p className=\"mt-1 text-xs text-red-700\">\n                      Already used. Change it a little, e.g. add\n                      &ldquo;-2&rdquo;.\n                    </p>\n                  )}\n                </Field>\n                <Field\n                  label=\"Title (Kiswahili)\"\n                  hint=\"Optional, but needed if you add Kiswahili text.\"\n                >\n                  <input\n                    className={input}\n                    value={item.titleSw ?? \"\"}\n                    onChange={(e) =>\n                      set(\"titleSw\", e.target.value || undefined)\n                    }\n                    maxLength={160}\n                  />\n                </Field>\n                <Field\n                  label=\"Summary\"\n                  hint=\"What he gains from it, in one or two short sentences.\"\n                >\n                  <textarea\n                    className={`${input} min-h-20`}\n                    value={item.summary}\n                    onChange={(e) => set(\"summary\", e.target.value)}\n                  />\n                </Field>\n                <Field\n                  label=\"Summary (Kiswahili)\"\n                  hint=\"Optional. Shown when a man uses the app in Kiswahili.\"\n                >\n                  <textarea\n                    lang=\"sw\"\n                    className={`${input} min-h-20`}\n                    value={item.summarySw ?? \"\"}\n                    onChange={(e) =>\n                      set(\"summarySw\", e.target.value || undefined)\n                    }\n                  />\n                </Field>\n              </Section>\n\n              {/* Content by type */}\n              <Section\n                title={\n                  item.kind === \"expert\"\n                    ? \"Question and answer\"\n                    : item.kind === \"video\"\n                      ? \"Video\"\n                      : item.kind === \"reel\"\n                        ? \"Reel (vertical video)\"\n                        : item.kind === \"audio\"\n                          ? \"Audio\"\n                          : item.kind === \"infographic\"\n                            ? \"Infographic\"\n                            : item.kind === \"quiz\"\n                              ? \"Quiz\"\n                              : \"Text\"\n                }\n              >\n                {item.kind === \"expert\" && (\n                  <Field label=\"The question a man asked\">\n                    <textarea\n                      className={`${input} min-h-16`}\n                      value={item.question ?? \"\"}\n                      onChange={(e) =>\n                        set(\"question\", e.target.value || undefined)\n                      }\n                    />\n                  </Field>\n                )}\n                {item.kind === \"infographic\" && (\n                  <p className=\"rounded-2xl bg-mint/60 px-4 py-3 text-xs text-forest-deep\">\n                    The infographic is the <b>cover photo</b> (upload it under\n                    Cover below). It&apos;s shown full size on the page; the\n                    text underneath is optional.\n                  </p>\n                )}\n                {item.kind === \"audio\" && (\n                  <div className=\"space-y-3\">\n                    {item.audioUrl && (\n                      <audio\n                        src={item.audioUrl}\n                        controls\n                        preload=\"metadata\"\n                        className=\"w-full\"\n                      />\n                    )}\n                    <div className=\"flex flex-wrap items-center gap-3\">\n                      <button\n                        type=\"button\"\n                        onClick={() => audioInput.current?.click()}\n                        disabled={busy === \"audio\"}\n                        className=\"flex items-center gap-2 rounded-full bg-forest px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-60\"\n                      >\n                        {busy === \"audio\" ? (\n                          <Loader2 size={16} className=\"animate-spin\" />\n                        ) : (\n                          <Mic size={16} />\n                        )}\n                        {busy === \"audio\"\n                          ? shrink\n                            ? \"Making it smaller…\"\n                            : \"Uploading…\"\n                          : item.audioUrl\n                            ? \"Change audio\"\n                            : \"Upload audio\"}\n                      </button>\n                      {item.audioUrl && (\n                        <button\n                          type=\"button\"\n                          onClick={() => set(\"audioUrl\", undefined)}\n                          className=\"flex items-center gap-1 text-sm font-semibold text-ink-soft\"\n                        >\n                          <X size={14} /> Remove audio\n                        </button>\n                      )}\n                      <input\n                        ref={audioInput}\n                        type=\"file\"\n                        accept=\"audio/*\"\n                        className=\"hidden\"\n                        onChange={(e) => uploadAudio(e.target.files?.[0])}\n                      />\n                      <span className=\"text-xs text-ink-soft\">\n                        MP3, M4A, AAC, OGG or WAV, under 40 MB.\n                      </span>\n                    </div>\n                    <Field\n                      label=\"Or paste an audio link\"\n                      hint=\"A direct https link to an .mp3 or .m4a file.\"\n                    >\n                      <input\n                        className={input}\n                        type=\"url\"\n                        placeholder=\"https://…/episode.mp3\"\n                        value={item.audioUrl ?? \"\"}\n                        onChange={(e) =>\n                          set(\"audioUrl\", e.target.value.trim() || undefined)\n                        }\n                      />\n                    </Field>\n                    <Field\n                      label=\"Key points\"\n                      hint=\"One per line. Shown under the player.\"\n                    >\n                      <textarea\n                        className={`${input} min-h-28`}\n                        value={texts.keyPoints}\n                        onChange={(e) => setText(\"keyPoints\", e.target.value)}\n                      />\n                    </Field>\n                  </div>\n                )}\n                {item.kind === \"reel\" && (\n                  <p className=\"rounded-2xl bg-mint/60 px-4 py-3 text-xs text-forest-deep\">\n                    A reel is a <b>vertical video</b> (filmed upright on a\n                    phone, 9:16), best under 90 seconds. It shows in the Reels\n                    row on Discover and in the feed, and plays full screen. The\n                    title and summary are its caption. A cover photo is optional\n                    (the first frame is used).\n                  </p>\n                )}\n                {(item.kind === \"video\" || item.kind === \"reel\") && (\n                  <div className=\"space-y-3\">\n                    {item.videoUrl && yt && (\n                      <YouTubeFrame\n                        id={yt}\n                        controls\n                        title={item.title || \"Video\"}\n                        onBlocked={() => setYtBlocked(item.videoUrl ?? null)}\n                        className={\n                          item.kind === \"reel\" || isYouTubeShort(item.videoUrl)\n                            ? \"mx-auto aspect-[9/16] max-h-[28rem] w-full max-w-[16rem] rounded-2xl\"\n                            : \"aspect-video w-full rounded-2xl\"\n                        }\n                      />\n                    )}\n                    {item.videoUrl && !yt && (\n                      <video\n                        src={item.videoUrl}\n                        controls\n                        playsInline\n                        preload=\"metadata\"\n                        className={\n                          item.kind === \"reel\"\n                            ? \"mx-auto aspect-[9/16] max-h-[28rem] rounded-2xl bg-black\"\n                            : \"aspect-video w-full rounded-2xl bg-black\"\n                        }\n                      />\n                    )}\n                    <div className=\"flex flex-wrap items-center gap-3\">\n                      <button\n                        type=\"button\"\n                        onClick={() => videoInput.current?.click()}\n                        disabled={busy === \"video\"}\n                        className=\"flex items-center gap-2 rounded-full bg-forest px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-60\"\n                      >\n                        {busy === \"video\" ? (\n                          <Loader2 size={16} className=\"animate-spin\" />\n                        ) : (\n                          <Film size={16} />\n                        )}\n                        {busy === \"video\"\n                          ? shrink\n                            ? \"Making it smaller…\"\n                            : \"Uploading…\"\n                          : item.videoUrl\n                            ? \"Change video\"\n                            : \"Upload video\"}\n                      </button>\n                      {item.videoUrl && (\n                        <button\n                          type=\"button\"\n                          onClick={() => set(\"videoUrl\", undefined)}\n                          className=\"flex items-center gap-1 text-sm font-semibold text-ink-soft\"\n                        >\n                          <X size={14} /> Remove video\n                        </button>\n                      )}\n                      <input\n                        ref={videoInput}\n                        type=\"file\"\n                        accept=\"video/mp4,video/webm,video/quicktime\"\n                        className=\"hidden\"\n                        onChange={(e) => uploadVideo(e.target.files?.[0])}\n                      />\n                      <span className=\"text-xs text-ink-soft\">\n                        {item.kind === \"reel\"\n                          ? \"MP4 or MOV, upright. Over 50 MB is made smaller for you (Chrome). Best under 90 seconds.\"\n                          : \"MP4, WebM or MOV. Over 50 MB is made smaller for you (Chrome). Short is best: 2 minutes or less.\"}\n                      </span>\n                    </div>\n                    <Field\n                      label=\"Or paste a video link\"\n                      hint=\"A YouTube link (plays inside the app) or a direct https link to an .mp4 file. Instagram links go in the post's origin, not here.\"\n                    >\n                      <input\n                        className={input}\n                        type=\"url\"\n                        placeholder=\"https://youtube.com/watch?v=… or https://…/video.mp4\"\n                        value={item.videoUrl ?? \"\"}\n                        onChange={(e) => pasteVideo(e.target.value)}\n                      />\n                    </Field>\n                    {shrinkNote}\n                    {ytNote}\n                  </div>\n                )}\n                {item.kind === \"video\" && (\n                  <Field\n                    label=\"Key points\"\n                    hint=\"One per line. Shown under the video.\"\n                  >\n                    <textarea\n                      className={`${input} min-h-28`}\n                      value={texts.keyPoints}\n                      onChange={(e) => setText(\"keyPoints\", e.target.value)}\n                    />\n                  </Field>\n                )}\n                {item.kind === \"quiz\" && (\n                  <QuizEditor\n                    value={item.quiz ?? []}\n                    onChange={(q) => set(\"quiz\", q)}\n                  />\n                )}\n                {item.kind === \"tool\" && (\n                  <Field group label=\"Which tool\">\n                    <div className=\"flex flex-wrap gap-2\">\n                      {TOOLS.map((t) => (\n                        <Chip\n                          key={t.id}\n                          on={item.tool === t.id}\n                          onClick={() => set(\"tool\", t.id)}\n                        >\n                          {t.label}\n                        </Chip>\n                      ))}\n                    </div>\n                  </Field>\n                )}\n                <Field\n                  label={\n                    item.kind === \"expert\"\n                      ? \"Answer (English)\"\n                      : \"Text (English)\"\n                  }\n                  hint='Leave an empty line between paragraphs. Start a line with \"## \" to make a heading.'\n                >\n                  <textarea\n                    className={`${input} min-h-56 leading-relaxed`}\n                    value={texts.body}\n                    onChange={(e) => setText(\"body\", e.target.value)}\n                  />\n                </Field>\n                <Field\n                  label=\"Text (Kiswahili)\"\n                  hint=\"Optional. Readers can switch language on the page.\"\n                >\n                  <textarea\n                    lang=\"sw\"\n                    className={`${input} min-h-40 leading-relaxed`}\n                    value={texts.bodySw}\n                    onChange={(e) => setText(\"bodySw\", e.target.value)}\n                  />\n                </Field>\n              </Section>\n\n              {/* Where men see it */}\n              <Section title=\"Where it shows\">\n                <ul className=\"flex flex-wrap gap-2\">\n                  {placesOf(item).map((p) => (\n                    <li\n                      key={p.id}\n                      className=\"flex items-center gap-1 rounded-full bg-mint/70 px-3 py-1.5 text-xs font-semibold text-forest-deep\"\n                    >\n                      <MapPin size={12} />\n                      {p.id === \"library\"\n                        ? `Library · ${TOPICS.find((t) => t.id === item.topic)?.title ?? \"no topic\"}`\n                        : p.title}\n                    </li>\n                  ))}\n                </ul>\n                <p className=\"text-xs text-ink-soft\">\n                  {item.kind === \"reel\"\n                    ? \"Reels show in the Reels row and between the cards on Discover. To put this one first for everyone, pin it in \"\n                    : \"Discover now shows reels and “do this” cards. Guides, articles and videos reach men through search, Saved, Kito, topic pages and links. To pin or hide things on Discover, use \"}\n                  <Link\n                    href=\"/studio/discover\"\n                    className=\"font-semibold text-forest underline\"\n                  >\n                    Studio → Discover\n                  </Link>\n                  .\n                </p>\n                <label className=\"flex items-start gap-3 text-sm\">\n                  <input\n                    type=\"checkbox\"\n                    className=\"mt-1 accent-forest\"\n                    checked={Boolean(item.inManFeed)}\n                    onChange={(e) => set(\"inManFeed\", e.target.checked)}\n                  />\n                  <span>\n                    <b>Show as a daily lesson on the Man tab</b>\n                    <span className=\"block text-xs text-ink-soft\">\n                      He earns the points below when he marks it as read.\n                    </span>\n                  </span>\n                </label>\n              </Section>\n\n              {/* Publishing: schedule, review, AI */}\n              <Section title=\"Publishing\">\n                <Field\n                  label=\"Go live at (optional)\"\n                  hint={\n                    item.publishAt && new Date(item.publishAt) > new Date()\n                      ? \"Scheduled: men see it from this time. Leave empty to go live as soon as it's published.\"\n                      : \"Leave empty to go live as soon as it's published. Pick a future time to schedule it.\"\n                  }\n                >\n                  <div className=\"flex flex-wrap items-center gap-2\">\n                    <input\n                      type=\"datetime-local\"\n                      className={`${input} max-w-xs`}\n                      value={item.publishAt ? toLocalInput(item.publishAt) : \"\"}\n                      onChange={(e) =>\n                        set(\n                          \"publishAt\",\n                          e.target.value\n                            ? new Date(e.target.value).toISOString()\n                            : undefined,\n                        )\n                      }\n                    />\n                    {item.publishAt && (\n                      <button\n                        type=\"button\"\n                        onClick={() => set(\"publishAt\", undefined)}\n                        className=\"text-xs font-semibold text-ink-soft\"\n                      >\n                        Clear\n                      </button>\n                    )}\n                  </div>\n                </Field>\n                <Field\n                  label=\"Note for review (optional)\"\n                  hint=\"What the writer or editor should know. Shown at the top while it's in review.\"\n                >\n                  <textarea\n                    className={`${input} min-h-16`}\n                    maxLength={500}\n                    value={item.reviewNote ?? \"\"}\n                    onChange={(e) =>\n                      set(\"reviewNote\", e.target.value || undefined)\n                    }\n                  />\n                </Field>\n                <label className=\"flex items-start gap-3 text-sm\">\n                  <input\n                    type=\"checkbox\"\n                    className=\"mt-1 accent-forest\"\n                    checked={Boolean(item.aiGenerated)}\n                    onChange={(e) =>\n                      set(\"aiGenerated\", e.target.checked || undefined)\n                    }\n                  />\n                  <span>\n                    <b>Drafted with AI help</b>\n                    <span className=\"block text-xs text-ink-soft\">\n                      For your records only. Staff can publish it straight away.\n                    </span>\n                  </span>\n                </label>\n              </Section>\n\n              {/* Look */}\n              <Section title=\"Cover\">\n                <div className=\"flex flex-wrap items-center gap-3\">\n                  <button\n                    type=\"button\"\n                    onClick={() => fileInput.current?.click()}\n                    disabled={busy === \"image\"}\n                    className=\"flex items-center gap-2 rounded-full bg-forest px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-60\"\n                  >\n                    {busy === \"image\" ? (\n                      <Loader2 size={16} className=\"animate-spin\" />\n                    ) : (\n                      <ImagePlus size={16} />\n                    )}\n                    {item.coverImageUrl ? \"Change photo\" : \"Upload photo\"}\n                  </button>\n                  {item.coverImageUrl && (\n                    <button\n                      type=\"button\"\n                      onClick={() => set(\"coverImageUrl\", undefined)}\n                      className=\"flex items-center gap-1 text-sm font-semibold text-ink-soft\"\n                    >\n                      <X size={14} /> Remove photo\n                    </button>\n                  )}\n                  <input\n                    ref={fileInput}\n                    type=\"file\"\n                    accept=\"image/jpeg,image/png,image/webp\"\n                    className=\"hidden\"\n                    onChange={(e) => upload(e.target.files?.[0])}\n                  />\n                  <span className=\"text-xs text-ink-soft\">\n                    JPG, PNG or WebP, under 3 MB. No intimate photos.\n                  </span>\n                </div>\n                {!item.coverImageUrl && (\n                  <Field group label=\"Or a drawn cover\">\n                    <div className=\"flex flex-wrap items-center gap-2\">\n                      {TONES.map((t) => (\n                        <button\n                          key={t}\n                          type=\"button\"\n                          aria-label={t}\n                          aria-pressed={item.cover.tone === t}\n                          onClick={() =>\n                            set(\"cover\", { ...item.cover, tone: t })\n                          }\n                          className={`h-8 w-8 rounded-full ring-1 ring-line ${item.cover.tone === t ? \"outline-2 outline-offset-2 outline-forest\" : \"\"}`}\n                          style={{ background: TONE_SWATCH[t] }}\n                        />\n                      ))}\n                      <span className=\"mx-1 h-6 w-px bg-line\" />\n                      {MOTIFS.map((m) => (\n                        <Chip\n                          key={m}\n                          on={item.cover.motif === m}\n                          onClick={() =>\n                            set(\"cover\", { ...item.cover, motif: m })\n                          }\n                        >\n                          {m[0].toUpperCase() + m.slice(1)}\n                        </Chip>\n                      ))}\n                    </div>\n                  </Field>\n                )}\n              </Section>\n\n              {/* Details */}\n              <Section title=\"Details\">\n                <div className=\"grid gap-4 sm:grid-cols-3\">\n                  <Field label=\"Minutes to read\">\n                    <input\n                      type=\"number\"\n                      min={1}\n                      max={60}\n                      className={input}\n                      value={item.minutes}\n                      onChange={(e) =>\n                        set(\"minutes\", clamp(e.target.value, 1, 60, 3))\n                      }\n                    />\n                  </Field>\n                  <Field\n                    label=\"Priority (0–100)\"\n                    hint=\"Higher comes first in search, topic pages and the Man tab.\"\n                  >\n                    <input\n                      type=\"number\"\n                      min={0}\n                      max={100}\n                      className={input}\n                      value={item.priority}\n                      onChange={(e) =>\n                        set(\"priority\", clamp(e.target.value, 0, 100, 50))\n                      }\n                    />\n                  </Field>\n                  <Field label=\"Points\">\n                    <input\n                      type=\"number\"\n                      min={0}\n                      max={100}\n                      className={input}\n                      value={item.points ?? 10}\n                      onChange={(e) =>\n                        set(\"points\", clamp(e.target.value, 0, 100, 10))\n                      }\n                    />\n                  </Field>\n                </div>\n                <Field\n                  label=\"Tags\"\n                  hint=\"Separate with commas. Helps search, e.g. sleep, energy, usingizi\"\n                >\n                  <input\n                    className={input}\n                    value={texts.tags}\n                    onChange={(e) => setText(\"tags\", e.target.value)}\n                  />\n                </Field>\n                <Field\n                  label=\"Source\"\n                  hint=\"Shown to readers: who wrote it and where facts come from.\"\n                >\n                  <input\n                    className={input}\n                    value={item.source}\n                    onChange={(e) => set(\"source\", e.target.value)}\n                  />\n                </Field>\n              </Section>\n            </>\n          )}\n        </div>\n\n        {/* Right side: checks and preview */}\n        <aside className=\"space-y-5\">\n          <div\n            className={`space-y-3 rounded-3xl bg-surface p-5 ring-1 ring-line ${quick ? \"hidden\" : \"\"}`}\n          >\n            <p className=\"font-bold\">Claim check</p>\n            {claims.length === 0 ? (\n              <p className=\"flex items-center gap-2 text-sm text-forest\">\n                <CheckCircle2 size={16} /> No selling, promises or contact\n                details found.\n              </p>\n            ) : (\n              <ul className=\"space-y-2\">\n                {[...blocks, ...warns].map((c, i) => (\n                  <li\n                    key={i}\n                    className={`flex gap-2 rounded-2xl px-3 py-2 text-xs ${c.level === \"block\" ? \"bg-red-50 text-red-800\" : \"bg-amber-50 text-amber-900\"}`}\n                  >\n                    {c.level === \"block\" ? (\n                      <OctagonX size={14} className=\"mt-px shrink-0\" />\n                    ) : (\n                      <AlertTriangle size={14} className=\"mt-px shrink-0\" />\n                    )}\n                    <span>\n                      <b>&ldquo;{c.match}&rdquo;</b> · {c.message}\n                    </span>\n                  </li>\n                ))}\n              </ul>\n            )}\n            <p className=\"pt-1 font-bold\">Ready to publish?</p>\n            {problems.length === 0 ? (\n              <p className=\"flex items-center gap-2 text-sm text-forest\">\n                <CheckCircle2 size={16} /> Yes, everything needed is there.\n              </p>\n            ) : (\n              <ul className=\"list-disc space-y-1 pl-5 text-xs text-ink-soft\">\n                {problems.map((p) => (\n                  <li key={p}>{p}</li>\n                ))}\n              </ul>\n            )}\n          </div>\n          <Preview item={item} />\n        </aside>\n      </div>\n\n      {/* Actions: stick to the bottom of the editor while scrolling */}\n      <div className=\"sticky bottom-0 z-20 -mx-4 border-t border-line bg-surface/95 px-4 py-3 backdrop-blur sm:-mx-6 sm:px-6 lg:-mx-8 lg:px-8\">\n        <div className=\"flex flex-wrap items-center gap-2\">\n          {error ? (\n            <p role=\"alert\" className=\"mr-auto max-w-md text-sm text-red-700\">\n              {error}\n            </p>\n          ) : (\n            <p className=\"mr-auto hidden text-xs text-ink-soft sm:block\">\n              {status === \"published\"\n                ? item.publishAt && new Date(item.publishAt) > new Date()\n                  ? \"Scheduled. Men see it from the time you set.\"\n                  : \"Men can see this now.\"\n                : status === \"review\"\n                  ? canPublish\n                    ? \"Waiting for your review.\"\n                    : \"Waiting for an editor to review.\"\n                  : canPublish\n                    ? \"Only staff can see drafts.\"\n                    : \"Writers submit for review; an editor publishes.\"}\n            </p>\n          )}\n          {status &&\n            status !== \"published\" &&\n            (canPublish || status !== \"archived\") && (\n              <button\n                onClick={() => setConfirmDelete(true)}\n                disabled={!!busy}\n                className={ghost}\n              >\n                <Trash2 size={14} /> Delete\n              </button>\n            )}\n          {status === \"published\" && canPublish && (\n            <>\n              <button\n                onClick={() => save(\"archived\")}\n                disabled={!!busy}\n                className={ghost}\n              >\n                <Archive size={14} /> Archive\n              </button>\n              <button\n                onClick={() => save(\"draft\")}\n                disabled={!!busy}\n                className={ghost}\n              >\n                Unpublish\n              </button>\n            </>\n          )}\n          {status !== \"published\" && (\n            <button\n              onClick={() => save(\"draft\")}\n              disabled={!!busy || (!dirty && status === \"draft\")}\n              className={ghost}\n            >\n              {busy === \"draft\" && (\n                <Loader2 size={14} className=\"animate-spin\" />\n              )}\n              {status === \"archived\"\n                ? \"Restore as draft\"\n                : status === \"review\"\n                  ? \"Back to draft\"\n                  : \"Save draft\"}\n            </button>\n          )}\n          {!canPublish &&\n            status !== \"published\" &&\n            status !== \"archived\" &&\n            (status !== \"review\" || dirty) && (\n              <button\n                onClick={() => save(\"review\")}\n                disabled={!!busy || problems.length > 0}\n                className={canPublish ? ghost : primaryBtn}\n              >\n                {busy === \"review\" && (\n                  <Loader2 size={14} className=\"animate-spin\" />\n                )}\n                {status === \"review\"\n                  ? \"Save review changes\"\n                  : \"Submit for review\"}\n              </button>\n            )}\n          {canPublish ? (\n            <button\n              onClick={() => save(\"published\")}\n              disabled={\n                !!busy ||\n                problems.length > 0 ||\n                (status === \"published\" && !dirty)\n              }\n              className={primaryBtn}\n            >\n              {busy === \"published\" && (\n                <Loader2 size={14} className=\"animate-spin\" />\n              )}\n              {item.publishAt && new Date(item.publishAt) > new Date()\n                ? status === \"published\"\n                  ? \"Update schedule\"\n                  : \"Schedule\"\n                : status === \"published\"\n                  ? \"Update live version\"\n                  : \"Publish\"}\n            </button>\n          ) : (\n            status === \"published\" && (\n              <p className=\"text-xs text-ink-soft\">\n                Live content can only be changed by an editor or owner.\n              </p>\n            )\n          )}\n        </div>\n      </div>\n\n      <Confirm\n        open={confirmDelete}\n        title={`Delete \"${item.title}\"?`}\n        confirmLabel=\"Delete for good\"\n        danger\n        typeToConfirm=\"delete\"\n        onConfirm={remove}\n        onClose={() => setConfirmDelete(false)}\n      >\n        It&apos;s removed from the Studio\n        {status === \"published\" ? \" and from the app\" : \"\"}. This can&apos;t be\n        undone. Earlier versions are deleted too. To keep it out of the app but\n        keep a copy, use Archive instead.\n      </Confirm>\n\n      <Drawer\n        open={showHistory}\n        title=\"Version history\"\n        onClose={() => setShowHistory(false)}\n      >\n        {versions === null ? (\n          <p className=\"flex items-center gap-2 text-sm text-ink-soft\">\n            <Loader2 size={16} className=\"animate-spin\" /> Loading…\n          </p>\n        ) : versions.length === 0 ? (\n          <p className=\"text-sm text-ink-soft\">\n            No earlier versions yet. Each time you save a change, the previous\n            version is kept here (the last 30).\n          </p>\n        ) : (\n          <ul className=\"space-y-2\">\n            {versions.map((v) => (\n              <li key={v.id} className=\"rounded-xl p-3 ring-1 ring-line\">\n                <div className=\"flex items-start justify-between gap-2\">\n                  <div className=\"min-w-0\">\n                    <p className=\"truncate text-sm font-semibold\">\n                      {v.item.title}\n                    </p>\n                    <p className=\"text-[0.6875rem] text-ink-soft\">\n                      <Clock size={11} className=\"mr-1 inline\" />\n                      {new Date(v.savedAt).toLocaleString(\"en-GB\", {\n                        day: \"numeric\",\n                        month: \"short\",\n                        hour: \"2-digit\",\n                        minute: \"2-digit\",\n                      })}{\" \"}\n                      · was {v.status}\n                    </p>\n                    <p className=\"mt-1 line-clamp-2 text-xs text-ink-soft\">\n                      {v.item.summary}\n                    </p>\n                  </div>\n                  <button onClick={() => loadVersion(v)} className={btn.small}>\n                    Load\n                  </button>\n                </div>\n              </li>\n            ))}\n          </ul>\n        )}\n      </Drawer>\n    </div>\n  );\n}\n\nfunction QuizEditor({\n  value,\n  onChange,\n}: {\n  value: QuizQuestion[];\n  onChange: (q: QuizQuestion[]) => void;\n}) {\n  const update = (i: number, patch: Partial<QuizQuestion>) =>\n    onChange(value.map((q, j) => (j === i ? { ...q, ...patch } : q)));\n  return (\n    <div className=\"space-y-4\">\n      {value.map((q, i) => (\n        <div\n          key={i}\n          className=\"space-y-3 rounded-2xl bg-bg p-4 ring-1 ring-line\"\n        >\n          <div className=\"flex items-center justify-between\">\n            <p className=\"text-xs font-bold text-ink-soft\">Question {i + 1}</p>\n            <button\n              type=\"button\"\n              onClick={() => onChange(value.filter((_, j) => j !== i))}\n              className=\"text-xs font-semibold text-ink-soft\"\n            >\n              Remove\n            </button>\n          </div>\n          <input\n            className={input}\n            placeholder=\"Question\"\n            value={q.q}\n            onChange={(e) => update(i, { q: e.target.value })}\n          />\n          {q.options.map((o, oi) => (\n            <label key={oi} className=\"flex items-center gap-2\">\n              <input\n                type=\"radio\"\n                name={`answer-${i}`}\n                className=\"accent-forest\"\n                checked={q.answer === oi}\n                onChange={() => update(i, { answer: oi })}\n                aria-label=\"Correct answer\"\n              />\n              <input\n                className={input}\n                placeholder={`Answer ${oi + 1}`}\n                value={o}\n                onChange={(e) =>\n                  update(i, {\n                    options: q.options.map((x, xi) =>\n                      xi === oi ? e.target.value : x,\n                    ),\n                  })\n                }\n              />\n            </label>\n          ))}\n          <p className=\"text-[0.6875rem] text-ink-soft\">\n            Tick the circle next to the correct answer.\n          </p>\n          <input\n            className={input}\n            placeholder=\"Why this is the answer (shown after he answers)\"\n            value={q.explain}\n            onChange={(e) => update(i, { explain: e.target.value })}\n          />\n        </div>\n      ))}\n      <button\n        type=\"button\"\n        onClick={() =>\n          onChange([\n            ...value,\n            { q: \"\", options: [\"\", \"\", \"\"], answer: 0, explain: \"\" },\n          ])\n        }\n        className=\"flex items-center gap-1.5 rounded-full px-4 py-2 text-sm font-semibold text-forest ring-1 ring-line\"\n      >\n        <Plus size={14} /> Add question\n      </button>\n    </div>\n  );\n}\n\nfunction Section({\n  title,\n  children,\n}: {\n  title: string;\n  children: React.ReactNode;\n}) {\n  return (\n    <section className=\"space-y-4 rounded-3xl bg-surface p-5 ring-1 ring-line\">\n      <h2 className=\"font-bold\">{title}</h2>\n      {children}\n    </section>\n  );\n}\n\n/** A labelled field. `group` is for rows of buttons (a <label> would make clicks on the text press the first button). */\nfunction Field({\n  label,\n  hint,\n  group,\n  children,\n}: {\n  label: string;\n  hint?: string;\n  group?: boolean;\n  children: React.ReactNode;\n}) {\n  const Tag = group ? \"div\" : \"label\";\n  return (\n    <Tag className=\"block\">\n      <span className=\"text-xs font-semibold text-ink-soft\">{label}</span>\n      <div className=\"mt-1\">{children}</div>\n      {hint && (\n        <span className=\"mt-1 block text-[0.6875rem] text-ink-soft\">\n          {hint}\n        </span>\n      )}\n    </Tag>\n  );\n}\n\nfunction Chip({\n  on,\n  onClick,\n  children,\n}: {\n  on: boolean;\n  onClick: () => void;\n  children: React.ReactNode;\n}) {\n  return (\n    <button\n      type=\"button\"\n      onClick={onClick}\n      aria-pressed={on}\n      className={`rounded-full px-3.5 py-1.5 text-xs font-semibold ${on ? \"bg-forest-deep text-white\" : \"bg-bg text-ink-soft ring-1 ring-line\"}`}\n    >\n      {children}\n    </button>\n  );\n}\n\n/** ISO time → value for <input type=\"datetime-local\"> in local time */\nconst toLocalInput = (iso: string) => {\n  const d = new Date(iso);\n  const pad = (n: number) => String(n).padStart(2, \"0\");\n  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;\n};\n\nconst clamp = (v: string, min: number, max: number, fallback: number) => {\n  const n = Math.round(Number(v));\n  return Number.isFinite(n) ? Math.min(max, Math.max(min, n)) : fallback;\n};\n\nconst input =\n  \"w-full rounded-2xl bg-bg px-4 py-2.5 text-sm outline-none ring-1 ring-line focus:ring-2 focus:ring-forest disabled:opacity-60\";\nconst primaryBtn =\n  \"flex items-center gap-1.5 rounded-full bg-forest px-5 py-2.5 text-sm font-semibold text-white transition-transform active:scale-[0.98] disabled:opacity-40\";\nconst ghost =\n  \"flex items-center gap-1.5 rounded-full px-4 py-2.5 text-sm font-semibold text-ink ring-1 ring-line disabled:opacity-40\";\n", "src/lib/studio/shrinkVideo.test.ts": "import { describe, expect, it } from \"vitest\";\nimport { maxSeconds, MIN_VIDEO_BPS, pickRecorderType, planShrink, TARGET_BYTES } from \"./shrinkVideo\";\n\ndescribe(\"shrinking big videos\", () => {\n  it(\"makes an upright phone video 720 wide and keeps a sharp bitrate for a short reel\", () => {\n    const p = planShrink(60, 1080, 1920)!;\n    expect([p.width, p.height]).toEqual([720, 1280]);\n    expect(p.videoBps).toBe(2_500_000);\n    // 60 s at that rate fits easily\n    expect(((p.videoBps + p.audioBps) * 60) / 8).toBeLessThan(TARGET_BYTES);\n  });\n  it(\"lowers the bitrate for longer videos so they still fit\", () => {\n    const p = planShrink(240, 1920, 1080)!;\n    expect([p.width, p.height]).toEqual([1280, 720]);\n    expect(((p.videoBps + p.audioBps) * 240) / 8).toBeLessThan(TARGET_BYTES);\n    expect(p.videoBps).toBeGreaterThanOrEqual(MIN_VIDEO_BPS);\n  });\n  it(\"doesn't make small videos bigger, and keeps sizes even\", () => {\n    const p = planShrink(30, 541, 961)!;\n    expect([p.width, p.height]).toEqual([542, 962]);\n  });\n  it(\"says no when the video is too long to fit\", () => {\n    expect(planShrink(maxSeconds() + 120, 1080, 1920)).toBeNull();\n    expect(planShrink(0, 1080, 1920)).toBeNull();\n  });\n  it(\"the second try uses a lower bitrate\", () => {\n    expect(planShrink(60, 1080, 1920, 0.6)!.videoBps).toBe(1_500_000);\n  });\n  it(\"prefers MP4, falls back to WebM\", () => {\n    expect(pickRecorderType((t) => t.startsWith(\"video/mp4\"))).toMatch(/^video\\/mp4/);\n    expect(pickRecorderType((t) => t.startsWith(\"video/webm\"))).toMatch(/^video\\/webm/);\n    expect(pickRecorderType(() => false)).toBeNull();\n  });\n});\n", "src/lib/studio/shrinkVideo.ts": "// Shrinking big videos in the Studio before upload (Step 75).\n// Supabase's free plan takes files up to 50 MB. A phone video is often much bigger because it's saved\n// at full quality. The browser plays the video once (silently), draws it at 720p, and records it again\n// at a lower bitrate: a 1-minute video takes about 1 minute. Works in Chrome/Edge on a computer and\n// Chrome on Android. Nothing leaves the computer until the smaller file is ready.\n\nimport { MAX_VIDEO_BYTES } from \"../content/repo\";\n\n/** Aim a little under the limit: the recorder's bitrate is only approximate. */\nexport const TARGET_BYTES = 44 * 1024 * 1024;\nconst AUDIO_BPS = 96_000;\n/** Below this, the picture gets too blurry: the video is too long to fit. */\nexport const MIN_VIDEO_BPS = 350_000;\n\nexport interface ShrinkPlan {\n  width: number;\n  height: number;\n  videoBps: number;\n  audioBps: number;\n}\n\nconst even = (n: number) => Math.max(2, Math.round(n / 2) * 2);\n\n/** The size and bitrate to record at, or null if the video is too long to fit in 50 MB. */\nexport function planShrink(duration: number, w: number, h: number, factor = 1, target = TARGET_BYTES): ShrinkPlan | null {\n  if (!(duration > 0) || !(w > 0) || !(h > 0)) return null;\n  const short = Math.min(w, h);\n  const scale = short > 720 ? 720 / short : 1;\n  const width = even(w * scale);\n  const height = even(h * scale);\n  // 720p looks sharp at 2.5 Mbps; smaller videos need less\n  const cap = Math.min(width, height) >= 700 ? 2_500_000 : 1_600_000;\n  const budget = ((target * 8) / duration) * 0.9 - AUDIO_BPS;\n  const videoBps = Math.floor(Math.min(cap, budget) * factor);\n  if (videoBps < MIN_VIDEO_BPS) return null;\n  return { width, height, videoBps, audioBps: AUDIO_BPS };\n}\n\n/** The longest video (in seconds) that still fits. */\nexport const maxSeconds = (target = TARGET_BYTES) => Math.floor(((target * 8) * 0.9) / (MIN_VIDEO_BPS + AUDIO_BPS));\n\n/** The best recording format this browser has: MP4 (plays everywhere) first, then WebM. */\nexport function pickRecorderType(isSupported: (t: string) => boolean): string | null {\n  for (const t of [\n    \"video/mp4;codecs=avc1.42E01F,mp4a.40.2\",\n    \"video/mp4;codecs=avc1.4D401F,mp4a.40.2\",\n    \"video/mp4;codecs=avc1,mp4a\",\n    \"video/mp4\",\n    \"video/webm;codecs=vp9,opus\",\n    \"video/webm;codecs=vp8,opus\",\n    \"video/webm\",\n  ])\n    if (isSupported(t)) return t;\n  return null;\n}\n\n/** Can this browser shrink videos? */\nexport function canShrink(): boolean {\n  if (typeof window === \"undefined\" || typeof MediaRecorder === \"undefined\") return false;\n  const c = document.createElement(\"canvas\") as HTMLCanvasElement & { captureStream?: unknown };\n  return typeof c.captureStream === \"function\" && pickRecorderType((t) => MediaRecorder.isTypeSupported(t)) !== null;\n}\n\nexport class ShrinkError extends Error {}\n\n/**\n * Make a video small enough to upload. Calls onProgress with 0–1.\n * Throws ShrinkError with a plain message when it can't (format, too long, cancelled).\n */\nexport async function shrinkVideo(file: File, opts: { onProgress?: (f: number, pass: number) => void; signal?: AbortSignal } = {}): Promise<File> {\n  const type = pickRecorderType((t) => MediaRecorder.isTypeSupported(t));\n  if (!type) throw new ShrinkError(\"This browser can't make videos smaller. Use Chrome, or shrink it in CapCut (Export → 720p).\");\n  for (const factor of [1, 0.6]) {\n    const out = await onePass(file, type, factor, factor === 1 ? 1 : 2, opts);\n    if (out.size <= MAX_VIDEO_BYTES) return out;\n  }\n  throw new ShrinkError(\"Even made smaller, this video is over 50 MB. Cut it shorter (under 5 minutes), or paste a YouTube link instead.\");\n}\n\nasync function onePass(file: File, type: string, factor: number, pass: number, opts: { onProgress?: (f: number, pass: number) => void; signal?: AbortSignal }): Promise<File> {\n  const url = URL.createObjectURL(file);\n  const video = document.createElement(\"video\");\n  video.src = url;\n  video.playsInline = true;\n  video.preload = \"auto\";\n  let ctx: AudioContext | null = null;\n  const cleanup = () => {\n    video.pause();\n    video.removeAttribute(\"src\");\n    video.load();\n    URL.revokeObjectURL(url);\n    void ctx?.close().catch(() => {});\n  };\n  try {\n    await new Promise<void>((ok, fail) => {\n      video.onloadedmetadata = () => ok();\n      video.onerror = () => fail(new ShrinkError(\"This browser can't read this video (often iPhone HEVC videos on Windows). Shrink it in CapCut (Export → 720p), then upload.\"));\n    });\n    const duration = video.duration;\n    if (!Number.isFinite(duration)) throw new ShrinkError(\"Couldn't read how long this video is. Shrink it in CapCut (Export → 720p), then upload.\");\n    const plan = planShrink(duration, video.videoWidth, video.videoHeight, factor);\n    if (!plan) throw new ShrinkError(`This video is too long to fit in 50 MB (${Math.round(duration / 60)} min). Keep it under ${Math.floor(maxSeconds() / 60)} minutes, or paste a YouTube link instead.`);\n\n    const canvas = document.createElement(\"canvas\");\n    canvas.width = plan.width;\n    canvas.height = plan.height;\n    const g = canvas.getContext(\"2d\");\n    if (!g) throw new ShrinkError(\"This browser can't make videos smaller. Use Chrome.\");\n    const tracks: MediaStreamTrack[] = [...(canvas as HTMLCanvasElement & { captureStream(fps?: number): MediaStream }).captureStream(30).getVideoTracks()];\n    // The sound goes straight into the recording, not out of the speakers\n    try {\n      ctx = new AudioContext();\n      const src = ctx.createMediaElementSource(video);\n      const dest = ctx.createMediaStreamDestination();\n      src.connect(dest);\n      tracks.push(...dest.stream.getAudioTracks());\n      await ctx.resume();\n    } catch {\n      video.muted = true; // no sound in the recording rather than no video\n    }\n\n    const rec = new MediaRecorder(new MediaStream(tracks), { mimeType: type, videoBitsPerSecond: plan.videoBps, audioBitsPerSecond: plan.audioBps });\n    const chunks: Blob[] = [];\n    rec.ondataavailable = (e) => e.data.size && chunks.push(e.data);\n    const stopped = new Promise<void>((ok) => (rec.onstop = () => ok()));\n\n    // Draw every frame as it plays\n    let running = true;\n    const v = video as HTMLVideoElement & { requestVideoFrameCallback?: (cb: () => void) => number };\n    const draw = () => {\n      if (!running) return;\n      g.drawImage(video, 0, 0, plan.width, plan.height);\n      opts.onProgress?.(Math.min(1, video.currentTime / duration), pass);\n      if (v.requestVideoFrameCallback) v.requestVideoFrameCallback(draw);\n      else requestAnimationFrame(draw);\n    };\n\n    const ended = new Promise<void>((ok, fail) => {\n      video.onended = () => ok();\n      video.onerror = () => fail(new ShrinkError(\"The video stopped playing while it was being made smaller. Try again.\"));\n      opts.signal?.addEventListener(\"abort\", () => fail(new ShrinkError(\"Stopped.\")));\n    });\n\n    video.currentTime = 0;\n    rec.start(1000);\n    try {\n      await video.play();\n    } catch {\n      rec.stop();\n      throw new ShrinkError(\"The browser blocked playing the video. Tap the upload button again.\");\n    }\n    draw();\n    try {\n      await ended;\n    } finally {\n      running = false;\n      if (rec.state !== \"inactive\") rec.stop();\n      await stopped;\n    }\n    const base = type.split(\";\")[0];\n    const name = file.name.replace(/\\.[^.]+$/, \"\") + (base === \"video/mp4\" ? \".mp4\" : \".webm\");\n    return new File(chunks, name, { type: base });\n  } finally {\n    cleanup();\n  }\n}\n"};
const BINARY = {};
const COMMIT_MSG = "Step 75: Studio shrinks videos over 50 MB to 720p in the browser before upload";
const mode = process.argv[2] ?? "write";

function run(label, cmd) {
  console.log(`\n▶ ${label}\n  $ ${cmd}`);
  const r = spawnSync(cmd, { stdio: "inherit", shell: true });
  if (r.status !== 0) {
    console.error(`\n✖ Failed at: ${label}. Fix the error above, then run again.`);
    process.exit(r.status ?? 1);
  }
  console.log(`✔ ${label}`);
}

if (!existsSync("package.json")) {
  console.error("✖ Run this inside the Men's Social project folder (where package.json is).");
  process.exit(1);
}

if (mode !== "commit") {
  run("Get latest code from GitHub", "git pull origin main");
  let changed = 0;
  const put = (path, data) => {
    mkdirSync(dirname(path), { recursive: true });
    if (existsSync(path)) {
      if (Buffer.compare(readFileSync(path), Buffer.from(data)) === 0) return;
      if (!path.startsWith("public/")) copyFileSync(path, path + ".bak");
    }
    writeFileSync(path, data);
    changed++;
  };
  for (const [p, t] of Object.entries(TEXT)) put(p, t);
  for (const [p, b] of Object.entries(BINARY)) put(p, Buffer.from(b, "base64"));
  console.log(`\n✔ ${changed} files written (${Object.keys(TEXT).length + Object.keys(BINARY).length} in this step)`);
  console.log("\nNext:  npm run dev     (then open http://localhost:3000)");
  console.log("Push:  node apply-step-75.mjs commit");
  console.log("No database change in this step.");
} else {
  // Before pushing: one build to be sure Netlify can build it too
  run("Build check", "npm run build");
  const paths = [...Object.keys(TEXT), ...Object.keys(BINARY)];
  for (let i = 0; i < paths.length; i += 40) run("Stage files", "git add -- " + paths.slice(i, i + 40).map((p) => JSON.stringify(p)).join(" "));
  run("Commit", `git commit -m ${JSON.stringify(COMMIT_MSG)}`);
  run("Push to GitHub", "git push origin main");
  try { (await import("node:fs")).rmSync(".next", { recursive: true, force: true }); } catch {}
  console.log("\n✅ Pushed. Netlify will deploy it in a few minutes.");
}
